<script setup>
import { ref, onMounted } from 'vue';
import { api } from '../../services/api.js';
import { auditAction,auditActor } from '../../services/audit.js';
import { money,date,statuses } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
import DataTable from '../../components/DataTable.vue';
import DashboardCharts from '../../components/DashboardCharts.vue';
const data=ref(null),error=ref(''),loading=ref(true);
onMounted(async()=>{try{data.value=await api.get('/admin/dashboard')}catch(e){error.value=e.message}finally{loading.value=false}});
const columns=[{key:'number',label:'Pedido'},{key:'customer.name',label:'Cliente'},{key:'total',label:'Total'},{key:'status',label:'Estado'}];
</script>
<template><div><header class="p-page-header"><div><p class="p-eyebrow">EL PULSO DE TU PLATAFORMA</p><h1>Todo tu negocio, en un lugar.</h1><p>Un vistazo a tus vendedores, tiendas y actividad reciente.</p></div><RouterLink to="/app/stores/new" class="btn btn-primary"><Icon name="plus" :size="16"/>Crear tienda</RouterLink></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/>Cargando resumen...</div><template v-else-if="data"><div class="p-stats"><article v-for="s in [{label:'Vendedores',value:data.users,icon:'users',note:'Usuarios de la plataforma'},{label:'Tiendas creadas',value:data.stores,icon:'store',note:`${data.activeStores||0} tiendas publicadas`},{label:'Ventas completadas',value:data.paidOrders,icon:'receipt',note:`${data.productsSold||0} unidades vendidas`},{label:'Volumen vendido',value:money(data.revenue),icon:'chart',note:'Total de todas las tiendas'}]" :key="s.label" class="p-stat"><span class="p-stat-icon"><Icon :name="s.icon" :size="17"/></span><span class="p-stat-label">{{s.label}}</span><strong class="p-stat-value">{{s.value??0}}</strong><small class="p-stat-note">{{s.note}}</small></article></div><div class="p-dashboard-grid"><DashboardCharts :series="data.salesSeries" :revenue="data.revenue"/><section class="p-section-card"><div class="p-section-title"><div><h2>Crecer empieza por acá</h2><p>Accesos rápidos a tu plataforma</p></div><Icon name="sparkles" :size="18"/></div><div class="p-checklist"><RouterLink to="/app/users/new"><span><Icon name="users" :size="18"/></span><span><strong>Sumá un nuevo vendedor</strong><small>Asignale su plan y su tienda</small></span><Icon name="chevron" :size="14"/></RouterLink><RouterLink to="/app/settings?tab=home"><span><Icon name="home" :size="18"/></span><span><strong>Personalizá tu página de inicio</strong><small>Contá todo lo que ofrecés</small></span><Icon name="chevron" :size="14"/></RouterLink><RouterLink to="/app/settings?tab=planes"><span><Icon name="crown" :size="18"/></span><span><strong>Diseñá tus planes</strong><small>Beneficios para cada etapa</small></span><Icon name="chevron" :size="14"/></RouterLink></div><hr class="p-separator"/><div class="p-inline"><span class="p-badge green">{{data.products||0}} productos creados</span><span class="p-badge blue">{{data.activeStores||0}} tiendas activas</span></div></section></div><div class="p-dashboard-grid"><section><div class="p-section-title"><div><h2>Últimos pedidos</h2><p>La actividad comercial de tus tiendas</p></div></div><DataTable :rows="data.recentOrders||[]" :columns="columns" :searchable="false" :limit="5" empty-text="Las primeras ventas están por llegar."><template #cell-total="{value}"><strong>{{money(value)}}</strong></template><template #cell-status="{value}"><span class="p-badge" :class="value">{{statuses[value]||value}}</span></template></DataTable></section><section class="p-section-card"><div class="p-section-title"><div><h2>Actividad reciente</h2><p>Operaciones de la plataforma</p></div><RouterLink to="/app/audit" class="btn btn-text">Ver todo</RouterLink></div><div v-for="item in (data.activity||[]).slice(0,6)" :key="item._id" class="p-activity-item"><span><Icon name="check" :size="14"/></span><div><RouterLink :to="'/app/audit/'+item._id"><strong>{{auditAction(item)}}</strong></RouterLink><small>{{auditActor(item)}}<template v-if="item.store?.name"> · {{item.store.name}}</template></small><small>{{date(item.createdAt)}}</small></div></div><p v-if="!data.activity?.length" class="p-muted">Las operaciones aparecerán acá.</p></section></div></template></div></template>
